output_text:
[
  {
    "id": "no_cart_singlefile_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles where shelves face the shopper on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_singlefile",
    "text": "A shopper must not enter a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "upperAisleMouth",
              "hasCart",
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_only_at_upper_mouths",
    "text": "Carts may be parked only at the wide mouth cells of the single-file upper aisles.",
    "abstraction": {
      "state_properties": {
        "approvedCartPark": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {
        "cartDropped": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartDropped",
          {
            "not": "approvedCartPark"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart at an upper aisle mouth, the shopper is obliged to retrieve it before leaving.",
    "abstraction": {
      "state_properties": {
        "approvedCartPark": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {
        "cartDroppedAtMouth": {
          "pre": {
            "and": [
              "approvedCartPark",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRetrievedAtMouth": {
          "pre": {
            "and": [
              "approvedCartPark",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDroppedAtMouth",
      "discharge": "cartRetrievedAtMouth"
    }
  },
  {
    "id": "upper_pick_requires_return_to_cart",
    "text": "After interacting with an item in a single-file upper aisle without a cart, the shopper must return and regain a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "upperShelfInteractionNoCart": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "cartRetrievedAtMouth": {
          "pre": {
            "and": [
              "upperAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "upperShelfInteractionNoCart",
      "discharge": "cartRetrievedAtMouth"
    }
  },
  {
    "id": "no_wandering_without_cart",
    "text": "Except in a single-file aisle or its cart-parking mouth, shoppers should not move around the store without their cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartFreeAllowedZone": {
          "or": [
            "singleFileShelfAisle",
            "upperAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "cartFreeAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "wide_shelf_interactions_need_cart",
    "text": "When shopping from shelves in wide or cart-accessible aisles, the shopper must have the cart with them.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartAccessibleShelfCell": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfCell",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_west",
    "text": "Customer traffic follows a one-way flow, so westward movement is prohibited.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "westMove": {
          "pre": "W",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "westMove"
    }
  }
]
